import random
from collections import defaultdict, deque

def bfs_girth_check(adj, n, forbidden_length=7):
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        queue = deque([start])
        dist[start] = 0
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle = dist[u] + dist[v] + 1
                    if cycle < forbidden_length:
                        return False
    return True

def try_generate(max_attempts=10000):
