    for attempt in range(max_attempts):
        # random degrees between 3 and 4, sum even
        degrees = [3] * n
        num_four = random.randrange(0, n+1, 2)
        for _ in range(num_four):
            degrees[random.randrange(n)] += 1
        # configuration model with multiple tries per degree seq
        for config_try in range(20):
            stubs = [i for i in range(n) for _ in range(degrees[i])]
            random.shuffle(stubs)
            adj = defaultdict(list)
            i = 0
            good = True
            seen = set()
            while i < len(stubs)-1 and good:
                u, v = stubs[i], stubs[i+1]
                if u == v:
                    good = False
                    break
                if u > v:
                    u, v = v, u
                if v in adj[u]:
                    good = False
                    break
                adj[u].append(v)
                adj[v].append(u)
                i += 2
            if not good or any(len(adj[k]) != degrees[k] for k in range(n)):
                continue
            # check girth
            if bfs_girth_check(adj, n):
                # convert to edge list
                edges = []
                for u in range(n):
                    for v in adj[u]:
                        if u < v:
                            edges.append((u, v))
                return sorted(edges)
    return None

