from collections import defaultdict, deque
import random

def bfs_has_short_cycle(adj, n=26):
    for s in range(n):
        dist = [-1] * n
        par = [-1] * n
        q = deque([s])
        dist[s] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    par[v] = u
                    q.append(v)
                elif v != par[u] and dist[v] >= 0:
                    if dist[u] + dist[v] + 1 < 7:
                        return True
    return False

def random_graph_with_deg(n=26, p=0.15, max_tries=500):
    for _ in range(max_tries):
        adj = defaultdict(list)
        for i in range(n):
            for j in range(i+1, n):
                if random.random() < p:
                    adj[i].append(j)
                    adj[j].append(i)
        degrees = [len(adj[i]) for i in range(n)]
        if min(degrees) < 3 or max(degrees) > 4:
            continue
        if not bfs_has_short_cycle(adj, n):
            edges = []
            for u in range(n):
                for v in adj[u]:
                    if u < v:
                        edges.append((u,v))
            return sorted(edges)
    return None

